-- Physical sample workflow sourced from Design Studio sample requests.
create sequence public.seq_factory_sample start 1;
create table public.factory_samples(sample_id uuid primary key default gen_random_uuid(),sample_no text not null unique,rfq_id uuid not null unique references public.rfqs(id),design_project_id uuid not null references public.design_projects(id),design_code text not null,design_name text not null,revision_no int not null,contact_name text not null,company text,email text not null,requested_quantity text,target_date date,assigned_to text,status text not null default'REQUESTED'check(status in('REQUESTED','IN_DEVELOPMENT','READY','SENT','APPROVED','REJECTED')),notes text,completed_at timestamptz,created_at timestamptz not null default now(),created_by text not null default'system',updated_at timestamptz not null default now(),updated_by text);
alter table public.factory_samples enable row level security;create policy factory_read_samples on public.factory_samples for select using(has_factory_role(auth.uid(),array['admin','production_manager','quality','viewer']));
create or replace function public.list_factory_sample_sources()returns table(rfq_id uuid,design_project_id uuid,design_code text,design_name text,family text,revision_no int,contact_name text,company text,email text,quantity text,quantity_unit text,target_date date,application text,message text)language sql stable security definer set search_path=public as $$select r.id,p.id,p.design_code,p.name,p.family::text,p.current_revision,r.contact_name,r.company,r.email,r.quantity,r.quantity_unit,r.target_date,r.application,r.message from rfqs r join design_projects p on p.id=r.project_id where has_factory_role(auth.uid(),array['admin','production_manager','quality','viewer'])and r.kind='sample'and r.status in('Submitted','Under Review')and not exists(select 1 from factory_samples s where s.rfq_id=r.id)order by r.created_at$$;
create or replace function public.create_factory_sample(p_rfq uuid,p_assigned_to text,p_target_date date default null,p_notes text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;v_no text;r record;begin if not has_factory_role(auth.uid(),array['admin','production_manager','quality'])then raise exception'not authorized';end if;if nullif(trim(p_assigned_to),'')is null then raise exception'assigned person is required';end if;select q.*,p.id project_id,p.design_code,p.name design_name,p.current_revision into r from rfqs q join design_projects p on p.id=q.project_id where q.id=p_rfq and q.kind='sample'and q.status in('Submitted','Under Review')for update of q,p;if not found then raise exception'sample request is unavailable';end if;v_no:='SMP-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('seq_factory_sample')::text,4,'0');insert into factory_samples(sample_no,rfq_id,design_project_id,design_code,design_name,revision_no,contact_name,company,email,requested_quantity,target_date,assigned_to,notes,created_by)values(v_no,p_rfq,r.project_id,r.design_code,r.design_name,r.current_revision,r.contact_name,r.company,r.email,concat_ws(' ',r.quantity,r.quantity_unit),coalesce(p_target_date,r.target_date),trim(p_assigned_to),nullif(trim(p_notes),''),auth.uid()::text)returning sample_id into v_id;update rfqs set status='Sample Development'where id=p_rfq;update design_projects set status='Sample Development',updated_at=now()where id=r.project_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Sample Development Created','factory_samples',v_id,jsonb_build_object('sample_no',v_no,'design_code',r.design_code,'assigned_to',trim(p_assigned_to)));return v_id;end$$;
create or replace function public.advance_factory_sample(p_sample uuid,p_status text,p_actor text,p_notes text default null)returns text language plpgsql security definer set search_path=public as $$declare s factory_samples;v_allowed text[];begin if not has_factory_role(auth.uid(),array['admin','production_manager','quality'])then raise exception'not authorized';end if;if nullif(trim(p_actor),'')is null then raise exception'actioned by is required';end if;select*into s from factory_samples where sample_id=p_sample for update;if not found then raise exception'sample not found';end if;v_allowed:=case s.status when'REQUESTED'then array['IN_DEVELOPMENT','REJECTED']when'IN_DEVELOPMENT'then array['READY','REJECTED']when'READY'then array['SENT','REJECTED']when'SENT'then array['APPROVED','REJECTED']else array[]::text[]end;if not(p_status=any(v_allowed))then raise exception'invalid transition from % to %',s.status,p_status;end if;if p_status='REJECTED'and nullif(trim(p_notes),'')is null then raise exception'rejection reason is required';end if;update factory_samples set status=p_status,notes=coalesce(nullif(trim(p_notes),''),notes),completed_at=case when p_status in('APPROVED','REJECTED')then now()else completed_at end,updated_at=now(),updated_by=auth.uid()::text where sample_id=p_sample;if p_status='APPROVED'then update design_projects set status='Sample Approved',updated_at=now()where id=s.design_project_id;update rfqs set status='Sample Approved'where id=s.rfq_id;elsif p_status='REJECTED'then update design_projects set status='Modification Required',updated_at=now()where id=s.design_project_id;update rfqs set status='Sample Rejected'where id=s.rfq_id;end if;insert into audit_log(user_id,action,entity_type,entity_id,old_value,new_value,reason)values(auth.uid(),'Sample Status Changed','factory_samples',p_sample,jsonb_build_object('status',s.status),jsonb_build_object('status',p_status,'actor',trim(p_actor)),nullif(trim(p_notes),''));return p_status;end$$;
revoke all on function public.list_factory_sample_sources()from public;revoke all on function public.create_factory_sample(uuid,text,date,text)from public;revoke all on function public.advance_factory_sample(uuid,text,text,text)from public;grant execute on function public.list_factory_sample_sources()to authenticated;grant execute on function public.create_factory_sample(uuid,text,date,text)to authenticated;grant execute on function public.advance_factory_sample(uuid,text,text,text)to authenticated;
